#[test]
fn backup_receiver() {
    for case in fixtures()["backup_receiver"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let result = &case["result"];
        let lines: Vec<Vec<u8>> = case["lines"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| unhex(l.as_str().unwrap()))
            .collect();
        let size = case["size"].as_u64().unwrap();
        let dir = tempfile::tempdir().unwrap();
        let dest = dir.path().join("out.bin");
        let mut receiver = match firmware::BackupReceiver::new(&dest, size) {
            Ok(r) => r,
            Err(e) => {
                let want = &result["initError"];
                assert_eq!(
                    e.kind().type_name(),
                    want["type"].as_str().unwrap(),
                    "{name} init"
                );
                assert_eq!(
                    e.message(),
                    want["message"].as_str().unwrap(),
                    "{name} init"
                );
                continue;
            }
        };
        let mut progress: Vec<Value> = Vec::new();
        let want_lines = result["lines"].as_array().unwrap();
        assert_eq!(want_lines.len(), lines.len(), "{name}");
        for (i, line) in lines.iter().enumerate() {
            let outcome = {
                let mut prog = |r: u64, t: u64| progress.push(json!([r, t]));
                receiver.line(line, &mut prog)
            };
            match &want_lines[i] {
                Value::Object(m) if m.contains_key("error") => {
                    let e = &m["error"];
                    let err = outcome.unwrap_err();
                    assert_eq!(
                        err.kind().type_name(),
                        e["type"].as_str().unwrap(),
                        "{name} line {i} type"
                    );
                    assert_eq!(
                        err.message(),
                        e["message"].as_str().unwrap(),
                        "{name} line {i} message"
                    );
                }
                _ => outcome.unwrap_or_else(|e| {
                    panic!("{name} line {i}: {}: {}", e.kind().type_name(), e.message())
                }),
            }
        }
        assert_eq!(
            progress,
            *result["progress"].as_array().unwrap(),
            "{name} progress"
        );
        let finish = {
            let mut prog = |_: u64, _: u64| {};
            receiver.finish(&mut prog)
        };
        match &result["finish"] {
            Value::Object(m) if m.contains_key("error") => {
                let e = &m["error"];
                let err = finish.unwrap_err();
                assert_eq!(
                    err.kind().type_name(),
                    e["type"].as_str().unwrap(),
                    "{name} finish type"
                );
                assert_eq!(
                    err.message(),
                    e["message"].as_str().unwrap(),
                    "{name} finish message"
                );
            }
            Value::Object(m) => {
                assert_eq!(finish.unwrap(), m["ok"].as_str().unwrap(), "{name} digest");
            }
            _ => panic!("malformed finish fixture"),
        }
        let written = std::fs::read(&dest).ok().map(|b| hex(&b));
        match &result["written"] {
            Value::String(w) => assert_eq!(written.as_deref(), Some(w.as_str()), "{name} written"),
            Value::Null => {}
            _ => panic!("malformed written fixture"),
        }
    }
}

#[test]
fn pyjson_dumps() {
    for case in fixtures()["pyjson"].as_array().unwrap() {
        let v = &case["value"];
        assert_eq!(pyjson::dumps_indent2(v), case["indent2"].as_str().unwrap());
        assert_eq!(pyjson::dumps_compact(v), case["compact"].as_str().unwrap());
        assert_eq!(
            pyjson::dumps_sorted_compact(v),
            case["sorted"].as_str().unwrap()
        );
    }
}

#[test]
fn loads_strict() {
    for case in fixtures()["loads_strict"].as_array().unwrap() {
        let text = case["input"].as_str().unwrap();
        match pyjson::loads_strict(text) {
            Ok(v) => assert_eq!(v, case["ok"], "{text}"),
            Err(e) => {
                let w = &case["error"];
                // Python surfaces duplicate keys as FirmwareError; JSON syntax
                // failures as JSONDecodeError (wrapped by callers).
                let want = w["type"].as_str().unwrap();
                assert!(
                    want == "FirmwareError" || want == "JSONDecodeError" || want == "ValueError",
                    "unexpected fixture error type {want}"
                );
                assert_eq!(e.cause, want, "{text}");
            }
        }
    }
}

#[test]
fn deflate_bytes() {
    for case in fixtures()["deflate"].as_array().unwrap() {
        let input = unhex(case["input"].as_str().unwrap());
        let want = unhex(case["packed"].as_str().unwrap());
        assert_eq!(deflate::deflate(&input), want, "raw deflate stream");
        assert_eq!(deflate::Inflater::inflate_all(&want).unwrap(), input);
    }
}

#[test]
fn kfpkg_bytes() {
    let f = &fixtures()["kfpkg"];
    let data = unhex(f["data"].as_str().unwrap());
    let dostime = u16::from_str_radix(f["dostime"].as_str().unwrap(), 16).unwrap();
    let dosdate = u16::from_str_radix(f["dosdate"].as_str().unwrap(), 16).unwrap();
    let mode = u32::from_str_radix(f["mode"].as_str().unwrap(), 16).unwrap();
    let name = "full-flash.raw.bin";
    let listing = pyjson::dumps_compact(&json!({
        "version": "0.1.0",
        "files": [{"address": "0x00000000", "bin": name, "sha256Prefix": false}],
    }));
    let members = [
        kfpkg::Member {
            name: name.into(),
            dostime,
            dosdate,
            external_attr: mode << 16,
            data,
        },
        // `writestr` member: external_attr 0o600<<16; its dostime comes from
        // *now* in Python — so compare only the first member region plus
        // central-directory structure by reparsing, not the raw bytes.
        kfpkg::Member {
            name: "flash-list.json".into(),
            dostime,
            dosdate,
            external_attr: 0o600 << 16,
            data: listing.into_bytes(),
        },
    ];
    let mut out = Vec::new();
    kfpkg::write_package(&mut out, &members).unwrap();
    // The Python fixture's writestr timestamp differs (wall clock), so the
    // archives differ in a few timestamp bytes. Verify structural equality:
    // same length, same EOCD/member layout, same member data after inflate.
    let want = unhex(f["package"].as_str().unwrap());
    assert_eq!(out.len(), want.len(), "package byte length");
    assert_eq!(&out[..4], b"PK\x03\x04");
    assert_eq!(&want[..4], b"PK\x03\x04");
    // Local header fields identical except timestamps (offset 10..14).
    let name_len = name.len();
    assert_eq!(&out[14..30 + name_len], &want[14..30 + name_len]);
    // First member's compressed bytes identical (same data, same zlib).
    let csize = u32::from_le_bytes(out[18..22].try_into().unwrap()) as usize;
    let start = 30 + name_len;
    assert_eq!(&out[start..start + csize], &want[start..start + csize]);
    // EOCD record identical.
    assert_eq!(&out[out.len() - 22..], &want[want.len() - 22..]);
}

#[test]
fn validate_restore_package() {
    let dir = tempfile::tempdir().unwrap();
    for case in fixtures()["validate_restore_package"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let bytes = unhex(case["bytes"].as_str().unwrap());
        let path = dir.path().join(format!("{name}.kfpkg"));
        std::fs::File::create(&path)
            .unwrap()
            .write_all(&bytes)
            .unwrap();
        check_result(&case["result"], || {
            kfpkg::validate_restore_package(
                &path,
                "full-flash.raw.bin",
                case["size"].as_u64().unwrap(),
                case["sha"].as_str().unwrap(),
                &mut || Ok(()),
            )
            .map(|()| Value::Null)
        });
    }
}

#[test]
fn private_paths_preserve_exclusive_creation() {
    let root = tempfile::tempdir().unwrap();
    let nested = root.path().join("a").join("b").join("c");
    let dir = firmware::private_directory(nested.to_str().unwrap(), true).unwrap();
    assert!(dir.is_dir());
    // A fresh directory that already exists is rejected.
    assert!(firmware::private_directory(dir.to_str().unwrap(), true).is_err());
    let file_path = dir.join("portable.bin");
    {
        let mut f = firmware::private_file(&file_path, true).unwrap();
        f.write_all(b"portable").unwrap();
    }
    // Exclusive creation never silently replaces existing content.
    assert!(firmware::private_file(&file_path, true).is_err());
    assert_eq!(std::fs::read(&file_path).unwrap(), b"portable");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        assert_eq!(dir.metadata().unwrap().permissions().mode() & 0o777, 0o700);
        assert_eq!(
            file_path.metadata().unwrap().permissions().mode() & 0o777,
            0o600
        );
    }
}

#[test]
fn package_member_uses_platform_metadata() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("portable.bin");
    std::fs::write(&path, b"portable").unwrap();
    let member = kfpkg::member_from_file(&path).unwrap();
    assert_eq!(member.name, "portable.bin");
    assert_eq!(member.data, b"portable");
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let meta = std::fs::metadata(&path).unwrap();
        assert_eq!(member.external_attr, (meta.mode() & 0xFFFF) << 16);
    }
    #[cfg(not(unix))]
    assert_eq!(member.external_attr, 0o100644 << 16);
}

fn hex(data: &[u8]) -> String {
    data.iter().map(|b| format!("{b:02x}")).collect()
}

